import type { CharacterKey } from '../core/types';
import type { TavernContext } from '../tavern/env';
import { close_active_dialog } from './dialog';
import { clear, el, on, play_enter_animation } from './dom';
import { icon } from './icons';
import { render_characters } from './pages/characters';
import { render_instructions } from './pages/instructions';
import { render_settings } from './pages/settings';
import { render_workspace } from './pages/workspace';

/** 主面板外壳。顶部栏负责标题、返回与齿轮，底部标签在两个一级页之间切换。 */

export type PanelPage =
  | { name: 'instructions' }
  | { name: 'characters' }
  | { name: 'settings' }
  | { name: 'workspace'; character_key: CharacterKey; title: string };

export interface PanelHooks {
  /** 面板显示或隐藏时通知外部。浮动工具条靠这个让位，避免压在面板按钮上面。 */
  on_visibility?: (visible: boolean) => void;
  /** 要求去聊天页面上挑段落收藏文本。 */
  on_collect_text?: (character_key: string) => void;
}

export interface PanelHandle {
  root: HTMLElement;
  backdrop: HTMLElement;
  open: (page?: PanelPage) => void;
  /** 只切页面，不把面板显示出来。用于跟随角色卡在后台换页。 */
  select: (page: PanelPage) => void;
  close: () => void;
  is_open: () => boolean;
  destroy: () => void;
}

export function create_panel(context: TavernContext | null, hooks: PanelHooks = {}): PanelHandle {
  const title_node = el('div', { class: 'yj-panel__title', text: '角色' });
  const subtitle_node = el('div', { class: 'yj-panel__subtitle' });
  const back_button = el('button', {
    class: 'yj-iconbtn yj-panel__back',
    html: icon('back', 19),
    title: '返回',
    attrs: { type: 'button', 'aria-label': '返回' },
  });
  const gear_button = el('button', {
    class: 'yj-iconbtn yj-panel__gear',
    html: icon('gear', 19),
    title: '设置',
    attrs: { type: 'button', 'aria-label': '设置' },
  });
  const close_button = el('button', {
    class: 'yj-iconbtn yj-panel__close',
    html: icon('close', 19),
    title: '关闭',
    attrs: { type: 'button', 'aria-label': '关闭' },
  });

  const body = el('div', { class: 'yj-panel__body' });

  const tab_instructions = el('button', {
    class: 'yj-tab',
    attrs: { type: 'button', 'data-page': 'instructions' },
  });
  tab_instructions.append(el('span', { html: icon('folder', 19) }), el('span', { text: '番外指令' }));

  const tab_characters = el('button', {
    class: 'yj-tab',
    attrs: { type: 'button', 'data-page': 'characters' },
  });
  tab_characters.append(el('span', { html: icon('user', 19) }), el('span', { text: '角色' }));

  const tabs = el('div', { class: 'yj-panel__tabs' }, [tab_instructions, tab_characters]);

  const bar = el('div', { class: 'yj-panel__bar' }, [
    back_button,
    title_node,
    subtitle_node,
    el('div', { class: 'yj-panel__actions' }, [gear_button, close_button]),
  ]);

  const root = el('div', { class: 'yj-panel' }, [bar, body, tabs]);
  const backdrop = el('div', { class: 'yj-backdrop' });

  let page: PanelPage = { name: 'characters' };

  function page_instructions(): HTMLElement {
    return render_instructions();
  }

  function page_characters(): HTMLElement {
    return render_characters(context, {
      on_open: (character_key, title) => {
        go({ name: 'workspace', character_key, title });
      },
    });
  }
  function page_settings(): HTMLElement {
    return render_settings();
  }

  function page_workspace(character_key: CharacterKey, title: string): HTMLElement {
    return render_workspace(context, character_key, title, {
      on_back: () => {
        go({ name: 'characters' });
      },
      on_collect_text: () => {
        hooks.on_collect_text?.(character_key);
      },
    });
  }

  function render(): void {
    close_active_dialog();
    clear(body);

    if (page.name === 'instructions') body.append(page_instructions());
    else if (page.name === 'settings') body.append(page_settings());
    else if (page.name === 'workspace') body.append(page_workspace(page.character_key, page.title));
    else body.append(page_characters());

    const is_settings = page.name === 'settings';
    const is_workspace = page.name === 'workspace';
    // 收藏库页自带「返回 + 角色名」的抬头，顶栏就不再重复，
    // 只留插件的名字，免得同一个角色名上下出现两遍。
    back_button.style.display = is_settings ? '' : 'none';
    tabs.style.display = is_settings || is_workspace ? 'none' : '';
    gear_button.classList.toggle('is-active', is_settings);

    title_node.textContent =
      page.name === 'settings'
        ? '设置'
        : page.name === 'instructions'
          ? '番外指令'
          : page.name === 'workspace'
            ? '月季管家'
            : '角色';
    subtitle_node.textContent = page.name === 'characters' ? '每个角色的收藏彼此独立' : '';
    subtitle_node.textContent = page.name === 'characters' ? '每个角色的收藏彼此独立' : '';

    tab_instructions.classList.toggle('is-active', page.name === 'instructions');
    tab_characters.classList.toggle('is-active', page.name === 'characters');
    body.scrollTop = 0;
  }

  function go(next: PanelPage): void {
    page = next;
    render();
    // 换页时让内容轻轻浮一下，比直接闪过去舒服。
    play_enter_animation(body, 'yj-anim-page');
  }

  const disposers: Array<() => void> = [
    on<Event>(tab_instructions, 'click', () => {
      go({ name: 'instructions' });
    }),
    on<Event>(tab_characters, 'click', () => {
      go({ name: 'characters' });
    }),
    on<Event>(gear_button, 'click', () => {
      go({ name: 'settings' });
    }),
    on<Event>(back_button, 'click', () => {
      go({ name: 'characters' });
    }),
    on<Event>(close_button, 'click', () => {
      api.close();
    }),
    on<Event>(backdrop, 'click', () => {
      api.close();
    }),
  ];

  const api: PanelHandle = {
    root,
    backdrop,
    open: next => {
      if (next) page = next;
      render();
      root.style.display = '';
      backdrop.style.display = '';
      play_enter_animation(root, 'yj-anim-panel');
      // 先量一下面板有没有真的渲染出尺寸。量不到就自己收起来，
      // 免得留下一个看不见、却拦着所有点击的整屏面板。
      requestAnimationFrame(() => {
        const rect = root.getBoundingClientRect();
        if (rect.width >= 1 && rect.height >= 1) {
          hooks.on_visibility?.(true);
          return;
        }
        console.warn('[月季管家] 面板没有渲染出尺寸，已自动收起。请把这条日志连同屏幕尺寸发给作者', {
          panel: { width: rect.width, height: rect.height },
          viewport: { width: window.innerWidth, height: window.innerHeight },
        });
        api.close();
      });
    },
    select: next => {
      page = next;
      render();
    },
    close: () => {
      close_active_dialog();
      root.style.display = 'none';
      backdrop.style.display = 'none';
      hooks.on_visibility?.(false);
    },
    is_open: () => root.style.display !== 'none',
    destroy: () => {
      for (const dispose of disposers) dispose();
    },
  };

  root.style.display = 'none';
  backdrop.style.display = 'none';
  render();

  return api;
}
