import { el, on } from './dom';
import { icon } from './icons';

/**
 * 页面角落常驻的浮动工具条。
 *
 * 交互约定（改之前先读这段）：
 * - 展开状态：[拖动条身][截图][文本收藏][花苞]。拖条身挪位置，轻点条身收起，点花苞开面板。
 * - 收起状态：只剩花苞。整条工具条都是「展开」热区，轻点任意位置都能展开。
 *   收起后条身是隐藏的，所以展开触发点不能只挂在条身上，否则收起来就再也点不开了。
 * - 收起状态下把花苞拖到靠近左右边缘，松手会吸附过去并藏起一半，露出的一截仍然点得到。
 *   展开时它会自己回到屏幕内。
 *
 * 三个实现上的注意点：
 * 1. 不用 setPointerCapture。一旦捕获，后续的 click 会被转交给被捕获的元素，
 *    里面的按钮就再也收不到点击。
 * 2. 位置夹取以视口为参照，不能用父节点。父节点是零高度的容器，会把工具条钉死在最上方。
 * 3. 按钮动作在 pointerup 就执行，不干等 click。移动端丢 click 的情况并不少见，
 *    只挂 click 会表现为「按钮完全点不动」。click 仍然保留，作为键盘操作的兜底。
 */

const STORAGE_KEY = 'yueji-guanjia.toolbar';
/** 存档结构版本。旧版本存过被钉在角落的错误位置，版本不匹配就丢弃重来。 */
const STATE_VERSION = 2;
/** 超过这个位移就当作拖动，而不是点击。手指点按的抖动比鼠标大，这里给宽一些。 */
const DRAG_THRESHOLD = 10;
/** 工具条离屏幕边缘的最小距离。 */
const EDGE_MARGIN = 6;
/** 收起后距离边缘多少像素以内就吸附过去。 */
const SNAP_DISTANCE = 34;
/** 吸附之后至少留多少像素在屏幕内，保证还点得到。 */
const SNAP_MIN_VISIBLE = 22;
/** pointerup 已经执行过动作之后，这段时间内的 click 一律忽略，避免一次点按触发两次。 */
const CLICK_FALLBACK_WINDOW = 600;

interface ToolbarState {
  version: number;
  left: number;
  top: number;
  collapsed: boolean;
}

type ToolbarAction = 'capture' | 'text' | 'home';

export interface ToolbarCallbacks {
  on_capture: () => void;
  on_text: () => void;
  on_home: () => void;
}

export interface ToolbarHandle {
  root: HTMLElement;
  /** 挂到容器上，并在有尺寸后校正位置。 */
  mount_into: (parent: HTMLElement) => void;
  destroy: () => void;
}

function load_state(): Partial<ToolbarState> {
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) return {};
    const parsed: unknown = JSON.parse(raw);
    if (!parsed || typeof parsed !== 'object') return {};
    const state = parsed as Partial<ToolbarState>;
    if (state.version !== STATE_VERSION) return {};
    return state;
  } catch (error) {
    console.warn('[月季管家] 读取工具条位置失败', error);
    return {};
  }
}

function save_state(state: ToolbarState): void {
  try {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  } catch (error) {
    console.warn('[月季管家] 保存工具条位置失败', error);
  }
}

/** 可视区域尺寸。以视口为准，不用任何父节点。 */
function viewport_size(): { width: number; height: number } {
  const width = window.innerWidth || document.documentElement.clientWidth || 0;
  const height = window.innerHeight || document.documentElement.clientHeight || 0;
  return { width, height };
}

export function create_toolbar(callbacks: ToolbarCallbacks): ToolbarHandle {
  const saved = load_state();
  let collapsed = saved.collapsed === true;
  let left = typeof saved.left === 'number' ? saved.left : Number.NaN;
  let top = typeof saved.top === 'number' ? saved.top : Number.NaN;
  /** 收起或展开导致宽度变化时，如果原本贴在右边缘，就继续保持贴右。 */
  let snap_right = false;
  /** 上一次由 pointerup 执行动作的时间，用来忽略随后的 click。 */
  let pointer_action_at = 0;

  let active_pointer: number | null = null;
  let down_target: EventTarget | null = null;
  let drag_start_x = 0;
  let drag_start_y = 0;
  let drag_from_left = 0;
  let drag_from_top = 0;
  let dragging = false;
  let disposers: Array<() => void> = [];

  const grip = el('div', { class: 'yj-toolbar__grip', html: icon('grip', 16) });
  const capture_button = el('button', {
    class: 'yj-toolbar__btn',
    html: icon('camera', 19),
    title: '截图',
    attrs: { type: 'button', 'aria-label': '截图', 'data-action': 'capture' },
  });
  const text_button = el('button', {
    class: 'yj-toolbar__btn',
    html: icon('bookmark', 19),
    title: '文本收藏',
    attrs: { type: 'button', 'aria-label': '文本收藏', 'data-action': 'text' },
  });
  const home_button = el('button', {
    class: 'yj-toolbar__btn yj-toolbar__home',
    html: icon('bud', 20),
    attrs: { type: 'button', 'data-action': 'home' },
  });

  const root = el('div', { class: 'yj-toolbar' }, [
    grip,
    capture_button,
    el('div', { class: 'yj-toolbar__divider' }),
    text_button,
    el('div', { class: 'yj-toolbar__divider' }),
    home_button,
  ]);

  function clamp(): void {
    const width = root.offsetWidth;
    const height = root.offsetHeight;
    if (!width || !height) return;
    const view = viewport_size();
    if (!view.width || !view.height) return;
    const max_left = Math.max(EDGE_MARGIN, view.width - width - EDGE_MARGIN);
    const max_top = Math.max(EDGE_MARGIN, view.height - height - EDGE_MARGIN);
    if (!Number.isFinite(left)) left = max_left;
    if (!Number.isFinite(top)) top = Math.round(view.height * 0.56);
    if (snap_right) left = max_left;
    left = Math.min(Math.max(EDGE_MARGIN, left), max_left);
    top = Math.min(Math.max(EDGE_MARGIN, top), max_top);
    root.style.left = `${Math.round(left)}px`;
    root.style.top = `${Math.round(top)}px`;
  }

  /** 收起状态下靠近左右边缘时算出吸附位置；不靠近或不是收起状态返回 null。 */
  function edge_snap_left(): number | null {
    if (!collapsed) return null;
    const width = root.offsetWidth;
    const view = viewport_size();
    if (!width || !view.width) return null;
    const visible = Math.max(SNAP_MIN_VISIBLE, Math.round(width * 0.5));
    const hidden = Math.max(0, width - visible);
    if (left <= SNAP_DISTANCE) return -hidden;
    if (view.width - (left + width) <= SNAP_DISTANCE) return view.width - visible;
    return null;
  }

  /** 先夹进屏幕，再决定要不要吸附。可以重复调用，结果稳定。 */
  function settle(): void {
    clamp();
    const snapped = edge_snap_left();
    if (snapped === null) return;
    left = snapped;
    root.style.left = `${Math.round(left)}px`;
  }

  function persist(): void {
    if (!Number.isFinite(left) || !Number.isFinite(top)) return;
    save_state({ version: STATE_VERSION, left, top, collapsed });
  }

  function is_at_right(): boolean {
    const width = root.offsetWidth;
    if (!width) return false;
    const view = viewport_size();
    return Number.isFinite(left) && left >= view.width - width - EDGE_MARGIN - 2;
  }

  function sync_labels(): void {
    grip.title = collapsed ? '' : '拖动移动，轻点收起';
    home_button.title = collapsed ? '展开月季管家工具条' : '打开月季管家';
    home_button.setAttribute('aria-label', home_button.title);
    root.title = collapsed ? '轻点展开' : '';
  }

  function apply_collapsed(): void {
    root.classList.toggle('is-collapsed', collapsed);
    sync_labels();
    requestAnimationFrame(() => {
      settle();
      snap_right = false;
      persist();
    });
  }

  function toggle_collapsed(): void {
    snap_right = is_at_right();
    collapsed = !collapsed;
    apply_collapsed();
  }

  function run_action(action: ToolbarAction): void {
    if (action === 'capture') callbacks.on_capture();
    else if (action === 'text') callbacks.on_text();
    else callbacks.on_home();
  }

  function stop_tracking(): void {
    window.removeEventListener('pointermove', on_pointer_move);
    window.removeEventListener('pointerup', on_pointer_up);
    window.removeEventListener('pointercancel', on_pointer_cancel);
  }

  function on_pointer_down(event: PointerEvent): void {
    if (event.pointerType === 'mouse' && event.button !== 0) return;
    active_pointer = event.pointerId;
    down_target = event.target;
    drag_start_x = event.clientX;
    drag_start_y = event.clientY;
    drag_from_left = Number.isFinite(left) ? left : 0;
    drag_from_top = Number.isFinite(top) ? top : 0;
    dragging = false;
    snap_right = false;
    window.addEventListener('pointermove', on_pointer_move);
    window.addEventListener('pointerup', on_pointer_up);
    window.addEventListener('pointercancel', on_pointer_cancel);
  }

  function on_pointer_move(event: PointerEvent): void {
    if (active_pointer !== event.pointerId) return;
    const dx = event.clientX - drag_start_x;
    const dy = event.clientY - drag_start_y;
    if (!dragging && Math.hypot(dx, dy) < DRAG_THRESHOLD) return;
    dragging = true;
    left = drag_from_left + dx;
    top = drag_from_top + dy;
    clamp();
  }

  function on_pointer_up(event: PointerEvent): void {
    if (active_pointer !== event.pointerId) return;
    active_pointer = null;
    stop_tracking();
    const target = down_target;
    down_target = null;

    if (dragging) {
      dragging = false;
      settle();
      persist();
      // 拖完浏览器还会补一个 click，别让它误触到按钮上。
      pointer_action_at = Date.now();
      return;
    }
    dragging = false;

    if (collapsed) {
      // 收起状态下整条工具条都是展开热区。
      toggle_collapsed();
      pointer_action_at = Date.now();
      return;
    }
    if (target instanceof Node && grip.contains(target)) {
      toggle_collapsed();
      pointer_action_at = Date.now();
      return;
    }

    const action_element = target instanceof Element ? target.closest('[data-action]') : null;
    const action = action_element?.getAttribute('data-action');
    if (action === 'capture' || action === 'text' || action === 'home') {
      run_action(action);
      pointer_action_at = Date.now();
    }
  }

  function on_pointer_cancel(event: PointerEvent): void {
    if (active_pointer !== event.pointerId) return;
    active_pointer = null;
    stop_tracking();
    down_target = null;
    dragging = false;
  }

  /** click 兜底：键盘回车或空格会走这里；pointerup 刚执行过就跳过，避免重复。 */
  function click_fallback(action: ToolbarAction): () => void {
    return () => {
      if (Date.now() - pointer_action_at < CLICK_FALLBACK_WINDOW) return;
      run_action(action);
    };
  }

  function on_resize(): void {
    settle();
  }

  disposers = [
    on<PointerEvent>(root, 'pointerdown', on_pointer_down),
    on<Event>(capture_button, 'click', click_fallback('capture')),
    on<Event>(text_button, 'click', click_fallback('text')),
    on<Event>(home_button, 'click', click_fallback('home')),
  ];

  window.addEventListener('resize', on_resize);
  window.addEventListener('orientationchange', on_resize);

  sync_labels();

  return {
    root,
    mount_into: parent => {
      parent.append(root);
      apply_collapsed();
    },
    destroy: () => {
      stop_tracking();
      window.removeEventListener('resize', on_resize);
      window.removeEventListener('orientationchange', on_resize);
      for (const dispose of disposers) dispose();
      disposers = [];
      root.remove();
    },
  };
}
