/** 角色在插件里的显示顺序与置顶。酒馆本身不提供排序，所以顺序存在本地。 */

const STORAGE_KEY = 'yueji-guanjia.char-order';

export interface CharacterOrder {
  /** 用户排好的显示顺序。不在这份名单里的角色排在后面，按酒馆原本的顺序。 */
  order: string[];
  /** 置顶的角色。只是用来画个图钉，位置信息在 order 里。 */
  pinned: string[];
}

function empty_order(): CharacterOrder {
  return { order: [], pinned: [] };
}

export function load_order(): CharacterOrder {
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) return empty_order();
    const parsed: unknown = JSON.parse(raw);
    if (!parsed || typeof parsed !== 'object') return empty_order();
    const record = parsed as Partial<CharacterOrder>;
    return {
      order: Array.isArray(record.order) ? record.order.filter(item => typeof item === 'string') : [],
      pinned: Array.isArray(record.pinned) ? record.pinned.filter(item => typeof item === 'string') : [],
    };
  } catch (error) {
    console.warn('[月季管家] 读取角色顺序失败', error);
    return empty_order();
  }
}

export function save_order(value: CharacterOrder): void {
  try {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(value));
  } catch (error) {
    console.warn('[月季管家] 保存角色顺序失败', error);
  }
}

/** 按保存的顺序排列；没记录过的角色按传入顺序接在后面。 */
export function arrange(keys: string[], saved: CharacterOrder): string[] {
  const known = saved.order.filter(key => keys.includes(key));
  const rest = keys.filter(key => !known.includes(key));
  return [...known, ...rest];
}

export function is_pinned(key: string, saved: CharacterOrder): boolean {
  return saved.pinned.includes(key);
}

/** 置顶就是把角色挪到顺序表最前面，并插上图钉。 */
export function pin(key: string, keys: string[], saved: CharacterOrder): CharacterOrder {
  const order = [key, ...arrange(keys, saved).filter(item => item !== key)];
  return { order, pinned: saved.pinned.includes(key) ? saved.pinned : [...saved.pinned, key] };
}

/** 取消置顶只摘图钉，位置的调整交给拖动，避免角色突然跳走。 */
export function unpin(key: string, saved: CharacterOrder): CharacterOrder {
  return { ...saved, pinned: saved.pinned.filter(item => item !== key) };
}
