import { apply_replace_rules, clean_text, split_paragraphs } from '../../core/search';
import { render_shot, resolve_shot_theme, type ShotRenderResult } from '../../core/shot_canvas';
import type { ShotBlock, ShotStyle } from '../../core/shot_layout';
import * as store from '../../core/store';
import type { CharacterKey, CharacterPrefs } from '../../core/types';
import type { TavernContext } from '../../tavern/env';
import { prompt_dialog } from '../dialog';
import { download_blob, shot_filename } from '../download';
import { el, on } from '../dom';
import { excerpt } from '../format';
import { icon } from '../icons';
import { toast } from '../toast';

/**
 * 截图流程：挑段落  生成预览  保存到本地或收进图库。
 *
 * 选择单位是「段落」，不是整个楼层。
 * 同一楼里挑中的段落会按原顺序接成一段连续文字；楼层之间各自独立成段，不做跨楼层拼接。
 *
 * 楼层正文在这里取，不去往聊天页面注入按钮：
 * 楼层 DOM 结构随酒馆版本变化，注入按钮在手机上也不好点，面板内选择能本地自测。
 */

export interface ShotFlowHandlers {
  /** 收进图库或取消之后，回到截图库。 */
  on_close: (changed: boolean) => void;
}

interface Message {
  name?: string;
  mes?: string;
  is_user?: boolean;
}

/** 一个可挑选的段落。 */
interface Paragraph {
  message_id: number;
  index: number;
  name: string;
  is_user: boolean;
  text: string;
}

/** 阅读卡片的排版参数。宽度是逻辑像素，实际像素密度由渲染器按内存预算决定。 */
const SHOT_STYLE: ShotStyle = {
  width: 760,
  font_size: 26,
  line_height: 44,
  padding: 44,
  block_gap: 26,
};

/** 一次最多挑多少段。挑太多既慢又容易超内存预算。 */
const MAX_PARAGRAPHS = 120;
/** 面板里只列最近这么多层。更早的楼层走页面上的截图按钮。 */
const MAX_FLOORS = 10;

function paragraph_key(item: Paragraph): string {
  return `${item.message_id}:${item.index}`;
}

export function render_shot_flow(
  context: TavernContext | null,
  character_key: CharacterKey,
  character_name: string,
  prefs: CharacterPrefs,
  handlers: ShotFlowHandlers,
): HTMLElement {
  const messages = (context?.chat ?? []) as Message[];
  const selected = new Set<string>();
  let title = '';
  let busy = false;
  let result: ShotRenderResult | null = null;
  let error = '';
  let preview_url: string | null = null;

  const page = el('section', { class: 'yj-page' });

  /** 清洗标签与模糊名词都在这里生效，所以挑选列表里看到的就是最终会画进图片的文字。 */
  function floor_text(message: Message | undefined): string {
    let text = typeof message?.mes === 'string' ? message.mes : '';
    text = clean_text(text, prefs.clean_tags);
    if (prefs.shot_replace_enabled && prefs.shot_replace_rules.length) {
      text = apply_replace_rules(text, prefs.shot_replace_rules);
    }
    return text;
  }

  /** 只取最近若干层，而且从最近的楼层开始排。更早的楼层走页面上的截图按钮。 */
  function collect_paragraphs(): Paragraph[][] {
    const groups: Paragraph[][] = [];
    let floors = 0;
    for (let message_id = messages.length - 1; message_id >= 0 && floors < MAX_FLOORS; message_id--) {
      const message = messages[message_id];
      const parts = split_paragraphs(floor_text(message));
      if (!parts.length) continue;
      const name = message.is_user ? '我' : message.name || '旁白';
      groups.push(
        parts.map((part, index) => ({
          message_id,
          index,
          name,
          is_user: message.is_user === true,
          text: part,
        })),
      );
      floors += 1;
    }
    return groups;
  }

  const paragraph_groups = collect_paragraphs();
  const all_paragraphs = paragraph_groups.flat();

  /** 挑中的段落整理成画布段落：同楼合并，楼层之间各自独立。 */
  function build_blocks(): ShotBlock[] {
    const picked = all_paragraphs.filter(item => selected.has(paragraph_key(item)));
    const by_message = new Map<number, Paragraph[]>();
    for (const item of picked) {
      const list = by_message.get(item.message_id) ?? [];
      list.push(item);
      by_message.set(item.message_id, list);
    }
    return [...by_message.keys()]
      .sort((lhs, rhs) => lhs - rhs)
      .map(message_id => {
        const list = (by_message.get(message_id) ?? []).sort((lhs, rhs) => lhs.index - rhs.index);
        return {
          name: list[0].name,
          text: list.map(item => item.text).join('\n\n'),
          is_user: list[0].is_user,
        };
      });
  }

  function back(on_click: () => void, label: string): HTMLElement {
    const button = el('button', {
      class: 'yj-iconbtn yj-ws__back',
      html: icon('back', 19),
      title: label,
      attrs: { type: 'button', 'aria-label': label },
    });
    on<Event>(button, 'click', on_click);
    return button;
  }

  /* ---------------------------------------------------------- 挑段落 */

  function paragraph_row(item: Paragraph): HTMLElement {
    const picked = selected.has(paragraph_key(item));
    const row = el('div', { class: `yj-row yj-row--tappable${picked ? ' is-picked' : ''}` }, [
      el('div', { class: `yj-pick${picked ? ' is-on' : ''}`, html: icon('check', 14) }),
      el('div', { class: 'yj-row__main' }, [el('div', { class: 'yj-row__meta', text: excerpt(item.text, 56) })]),
    ]);
    on<Event>(row, 'click', () => {
      const key = paragraph_key(item);
      if (selected.has(key)) selected.delete(key);
      else if (selected.size >= MAX_PARAGRAPHS) toast(`一次最多挑 ${MAX_PARAGRAPHS} 段`);
      else selected.add(key);
      render();
    });
    return row;
  }

  function floor_group(list: Paragraph[]): HTMLElement {
    const keys = list.map(paragraph_key);
    const all_picked = keys.every(key => selected.has(key));

    const toggle = el('button', {
      class: 'yj-btn yj-btn--ghost yj-group__toggle',
      text: all_picked ? '取消本层' : '全选本层',
      attrs: { type: 'button' },
    });
    on<Event>(toggle, 'click', () => {
      if (all_picked) {
        for (const key of keys) selected.delete(key);
      } else {
        for (const key of keys) {
          if (selected.size >= MAX_PARAGRAPHS) break;
          selected.add(key);
        }
      }
      render();
    });

    const head = el('div', { class: 'yj-group__head' }, [
      el('div', { class: 'yj-group__name', text: list[0].name }),
      el('div', { class: 'yj-group__meta', text: `第 ${list[0].message_id + 1} 楼 · ${list.length} 段` }),
      toggle,
    ]);

    return el('div', { class: 'yj-group' }, [head, el('div', { class: 'yj-card' }, list.map(paragraph_row))]);
  }

  function select_view(): HTMLElement {
    const head = el('section', { class: 'yj-ws__head' }, [
      back(() => {
        handlers.on_close(false);
      }, '返回截图库'),
      el('div', { class: 'yj-ws__title', text: '挑要截的段落' }),
    ]);

    const hint = el('div', { class: 'yj-note' }, [
      el('div', { text: '点段落就选中，可以跳着挑。同一楼里挑中的段落会按原顺序接在一起，不会把中间没挑的带进来。' }),
      el('div', { text: '这里只列最近 10 层。要挑更早的楼层，用页面上的截图按钮。' }),
      el('div', {
        text: prefs.clean_tags.length
          ? '已按清洗标签过滤，状态栏这类结构不会进图片。'
          : '只取正文，状态栏和时间组件不进图片。',
      }),
    ]);

    const groups = paragraph_groups.map(list => floor_group(list));

    const generate = el('button', {
      class: 'yj-btn yj-btn--primary',
      text: selected.size ? `生成预览（${selected.size} 段）` : '先挑段落',
      attrs: { type: 'button' },
    });
    if (!selected.size) generate.setAttribute('disabled', 'true');
    on<Event>(generate, 'click', () => {
      if (!selected.size) return;
      void run_render();
    });

    if (!groups.length) {
      return el('section', { class: 'yj-page' }, [
        head,
        el('div', { class: 'yj-empty' }, [
          el('div', { class: 'yj-empty__mark', html: icon('camera', 30) }),
          el('div', {
            class: 'yj-empty__text',
            text: prefs.clean_tags.length
              ? '按现在的清洗标签过滤之后，这个聊天里没有剩下可以截的段落。'
              : '这个聊天里还没有可以截的正文。',
          }),
        ]),
      ]);
    }

    return el('section', { class: 'yj-page' }, [
      head,
      hint,
      ...groups,
      el('div', { class: 'yj-detail__actions' }, [generate]),
    ]);
  }

  /* ---------------------------------------------------------- 预览 */

  function preview_view(): HTMLElement {
    const head = el('section', { class: 'yj-ws__head' }, [
      back(() => {
        if (preview_url) URL.revokeObjectURL(preview_url);
        preview_url = null;
        result = null;
        render();
      }, '返回重挑'),
      el('div', { class: 'yj-ws__title', text: '预览' }),
    ]);

    const parts: HTMLElement[] = [head];

    if (busy) {
      parts.push(el('div', { class: 'yj-empty' }, [el('div', { class: 'yj-empty__text', text: '正在生成图片' })]));
      return el('section', { class: 'yj-page' }, parts);
    }

    if (error || !result?.blob) {
      parts.push(
        el('div', { class: 'yj-empty' }, [
          el('div', { class: 'yj-empty__mark', html: icon('camera', 30) }),
          el('div', { class: 'yj-empty__text', text: error || '图片没有生成成功。' }),
        ]),
      );
      return el('section', { class: 'yj-page' }, parts);
    }

    if (preview_url) URL.revokeObjectURL(preview_url);
    preview_url = URL.createObjectURL(result.blob);
    const image = el('img', { class: 'yj-preview__image', attrs: { src: preview_url, alt: '截图预览' } });
    parts.push(el('div', { class: 'yj-preview' }, [image]));
    parts.push(
      el('div', {
        class: 'yj-row__meta',
        text: `${result.width}  ${result.height} 像素  ${selected.size} 段`,
      }),
    );

    if (result.truncated) {
      parts.push(
        el('div', { class: 'yj-note yj-note--warn' }, [
          el('div', {
            text: `内容太长，这台设备一次画不完。图里只放了前面一部分，挑中的 ${selected.size} 段没有全部进去。想要完整图请少挑几段分两次截。`,
          }),
        ]),
      );
    }

    const title_input = el('input', {
      class: 'yj-input',
      attrs: { type: 'text', placeholder: '给这张图起个标题（可不填）', value: title },
    });
    on<Event>(title_input, 'input', () => {
      title = title_input.value;
    });
    parts.push(el('div', { class: 'yj-editor__field' }, [title_input]));

    const save_local = el('button', {
      class: 'yj-btn yj-btn--ghost',
      text: '保存到本地',
      attrs: { type: 'button' },
    });
    on<Event>(save_local, 'click', () => {
      if (!result?.blob) return;
      download_blob(result.blob, shot_filename(title || character_name));
      toast('已生成图片，看看浏览器的下载');
    });

    const collect = el('button', {
      class: 'yj-btn yj-btn--primary',
      text: '收进图库',
      attrs: { type: 'button' },
    });
    on<Event>(collect, 'click', () => {
      void collect_to_library();
    });

    parts.push(el('div', { class: 'yj-detail__actions' }, [save_local, collect]));
    return el('section', { class: 'yj-page' }, parts);
  }

  /* ---------------------------------------------------------- 动作 */

  async function run_render(): Promise<void> {
    busy = true;
    error = '';
    render();
    const blocks = build_blocks();
    if (!blocks.length) {
      busy = false;
      error = '挑中的段落清洗之后没有剩下正文。';
      render();
      return;
    }
    try {
      result = await render_shot({
        blocks,
        style: SHOT_STYLE,
        title,
        footer: `${character_name}  ${new Date().toLocaleDateString('zh-CN')}`,
        theme: resolve_shot_theme(prefs.shot_theme, prefs.shot_background, prefs.shot_ink),
        background_image:
          prefs.shot_theme === 'image' && prefs.shot_background_image
            ? { source: prefs.shot_background_image, mode: prefs.shot_background_mode }
            : undefined,
      });
    } catch (failure) {
      console.warn('[月季管家] 生成截图失败', failure);
      error = failure instanceof Error ? failure.message : '生成图片失败。';
    }
    busy = false;
    render();
  }

  async function collect_to_library(): Promise<void> {
    if (!result?.blob) return;
    let name = title.trim();
    if (!name) {
      const answer = await prompt_dialog({
        title: '给这张截图起个标题',
        confirm_text: '收藏',
        input: { placeholder: '例如：雨夜的对话' },
      });
      if (answer === null) return;
      name = answer || '未命名';
      title = name;
    }
    try {
      await store.put_shot(
        {
          id: store.new_id(),
          character_key,
          title: name,
          created_at: Date.now(),
          width: result.width,
          height: result.height,
          bytes: result.blob.size,
          starred: false,
          thumb: result.thumb,
        },
        result.blob,
      );
      toast('已收进图库');
      handlers.on_close(true);
    } catch (failure) {
      console.warn('[月季管家] 收藏截图失败', failure);
      toast('收藏失败');
    }
  }

  function render(): void {
    page.replaceChildren(result || busy || error ? preview_view() : select_view());
  }

  render();
  return page;
}
