import { el, on, play_enter_animation, shadow_layer } from './dom';

/**
 * 面板内的弹窗。确认框与输入框共用一套外观。
 * 不用酒馆自带的 popup，是为了让黑白风格在插件里保持一致。
 */

export interface AskOptions {
  title: string;
  message?: string;
  confirm_text?: string;
  cancel_text?: string;
  danger?: boolean;
  /** 传了就是输入框，没传就是纯确认。 */
  input?: { placeholder?: string; value?: string };
}

let active_close: (() => void) | null = null;

/** 关掉当前还开着的弹窗。切换页面时调用，避免弹窗挂在半空中。 */
export function close_active_dialog(): void {
  active_close?.();
}

function ask(options: AskOptions): Promise<string | null> {
  const layer = shadow_layer();
  if (!layer) return Promise.resolve(null);
  // 同时只允许一个弹窗，先关掉之前的。
  close_active_dialog();

  return new Promise<string | null>(resolve => {
    let settled = false;

    const title = el('div', { class: 'yj-dialog__title', text: options.title });
    const head = el('div', { class: 'yj-dialog__head' }, [title]);

    const parts: HTMLElement[] = [];
    if (options.message) parts.push(el('div', { class: 'yj-dialog__message', text: options.message }));

    let input: HTMLInputElement | null = null;
    if (options.input) {
      input = el('input', {
        class: 'yj-dialog__input',
        attrs: {
          type: 'text',
          placeholder: options.input.placeholder ?? '',
          value: options.input.value ?? '',
          enterkeyhint: 'done',
        },
      });
      parts.push(input);
    }
    const body = el('div', { class: 'yj-dialog__body' }, parts);

    const cancel_button = el('button', {
      class: 'yj-btn yj-btn--ghost',
      text: options.cancel_text ?? '取消',
      attrs: { type: 'button' },
    });
    const confirm_button = el('button', {
      class: `yj-btn ${options.danger ? 'yj-btn--danger' : 'yj-btn--primary'}`,
      text: options.confirm_text ?? '确定',
      attrs: { type: 'button' },
    });
    const actions = el('div', { class: 'yj-dialog__actions' }, [cancel_button, confirm_button]);

    const card = el('div', { class: 'yj-dialog' }, [head, body, actions]);
    const backdrop = el('div', { class: 'yj-dialog__backdrop' });
    const wrapper = el('div', { class: 'yj-dialog__layer' }, [backdrop, card]);
    layer.append(wrapper);
    play_enter_animation(card, 'yj-anim-dialog');

    const disposers: Array<() => void> = [];

    function finish(value: string | null): void {
      if (settled) return;
      settled = true;
      for (const dispose of disposers) dispose();
      if (active_close === finish) active_close = null;
      wrapper.remove();
      resolve(value);
    }

    disposers.push(
      on<Event>(backdrop, 'click', () => {
        finish(null);
      }),
      on<Event>(cancel_button, 'click', () => {
        finish(null);
      }),
      on<Event>(confirm_button, 'click', () => {
        finish(input ? input.value.trim() : '');
      }),
      on<KeyboardEvent>(document, 'keydown', event => {
        if (event.key === 'Escape') {
          event.stopPropagation();
          finish(null);
        } else if (event.key === 'Enter' && input) {
          finish(input.value.trim());
        }
      }),
    );

    active_close = () => {
      finish(null);
    };

    requestAnimationFrame(() => {
      if (input) {
        input.focus();
        input.select();
      } else {
        confirm_button.focus();
      }
    });
  });
}

export function confirm_dialog(options: AskOptions): Promise<boolean> {
  return ask(options).then(value => value !== null);
}

export function prompt_dialog(options: AskOptions): Promise<string | null> {
  return ask({ ...options, input: options.input ?? {} });
}
