import { layout_shot, type ShotBlock, type ShotLayout, type ShotMeasure, type ShotStyle } from './shot_layout';
import type { ShotBackgroundMode, ShotThemeKind } from './types';

/**
 * 把选中的楼层画成一张长图。
 *
 * 这里是自己把正文排版进 canvas，没有引入渲染库。原因：
 * 要的就是「只取正文、去掉状态栏、跨楼层无缝拼成一段连续对话」，
 * 这些对纯文本排版来说都是天然满足的，不需要去啃 DOM 转图片那一堆兼容问题。
 * 代价是图片里是干净的正文，不是聊天界面的像素级复制。
 *
 * 内存控制（手机上最容易出事的地方）：
 * - 先按 1 倍排一遍量出真实高度，再决定用几倍像素密度，尽量取高清但不超过预算。
 * - 单边不超过 MAX_SIDE，总像素不超过 MAX_PIXELS。两个上限都是为了让 iOS 不返回白图。
 * - 万一内容长到连 1 倍都放不下，就按高度截断，并在结果里标明截断了几层。
 */

/** 单边上限。很多设备超过这个尺寸会直接返回空白画布。 */
const MAX_SIDE = 16000;
/** 总像素上限。iOS 上超过这个量级很容易崩。 */
const MAX_PIXELS = 16_000_000;
/** 像素密度候选，从高到低试，取第一个放得下的。 */
const SCALE_STEPS = [2, 1.75, 1.5, 1.25, 1];
/** 量高度时给一个宽松上限，避免超长内容把第一次排版也拖死。 */
const MEASURE_LIMIT = MAX_SIDE * 4;

const SANS = '"PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", "Noto Sans SC", system-ui, sans-serif';
const SERIF = '"Songti SC", "Noto Serif SC", "Source Han Serif SC", "SimSun", serif';

export interface ShotTheme {
  background: string;
  ink: string;
  muted: string;
  line: string;
}

export const SHOT_THEMES: Record<'classic' | 'inverted', ShotTheme> = {
  /** 经典款：白底黑字。 */
  classic: { background: '#ffffff', ink: '#17171a', muted: '#8a8a8e', line: '#e6e6e9' },
  /** 黑底白字款。 */
  inverted: { background: '#141416', ink: '#f1f1f3', muted: '#8f8f96', line: '#2b2b31' },
};

/** 把两个十六进制颜色按比例混一下，用来从背景与字色推出次要色和分隔线。 */
function mix_hex(from: string, to: string, ratio: number): string {
  const parse = (value: string): [number, number, number] => {
    const hex = value.trim().replace(/^#/, '');
    const full =
      hex.length === 3
        ? hex
            .split('')
            .map(char => char + char)
            .join('')
        : hex.padEnd(6, '0').slice(0, 6);
    const number = Number.parseInt(full, 16);
    if (!Number.isFinite(number)) return [0, 0, 0];
    return [(number >> 16) & 255, (number >> 8) & 255, number & 255];
  };
  const [r1, g1, b1] = parse(from);
  const [r2, g2, b2] = parse(to);
  const blend = (lhs: number, rhs: number) => Math.round(lhs + (rhs - lhs) * Math.min(1, Math.max(0, ratio)));
  const to_hex = (value: number) => value.toString(16).padStart(2, '0');
  return `#${to_hex(blend(r1, r2))}${to_hex(blend(g1, g2))}${to_hex(blend(b1, b2))}`;
}

/** 按偏好里的款式设置算出真正用来画的颜色。 */
export function resolve_shot_theme(kind: ShotThemeKind, background: string, ink: string): ShotTheme {
  if (kind === 'inverted') return SHOT_THEMES.inverted;
  if (kind === 'image') {
    // 图片读不出来时的兜底纯色，字体色仍然由作者定。
    const safe_background = /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.test(background.trim()) ? background.trim() : '#ffffff';
    const safe_ink = /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.test(ink.trim()) ? ink.trim() : '#17171a';
    return {
      background: safe_background,
      ink: safe_ink,
      muted: mix_hex(safe_ink, safe_background, 0.35),
      line: mix_hex(safe_ink, safe_background, 0.7),
    };
  }
  if (kind === 'custom') {
    const safe_background = /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.test(background.trim()) ? background.trim() : '#ffffff';
    const safe_ink = /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.test(ink.trim()) ? ink.trim() : '#17171a';
    return {
      background: safe_background,
      ink: safe_ink,
      muted: mix_hex(safe_ink, safe_background, 0.45),
      line: mix_hex(safe_ink, safe_background, 0.82),
    };
  }
  return SHOT_THEMES.classic;
}

/** 图片背景。地址可以是 http(s) 或 data URL。 */
export interface ShotBackgroundImage {
  source: string;
  mode: ShotBackgroundMode;
}

export interface ShotRenderInput {
  blocks: ShotBlock[];
  style: ShotStyle;
  title: string;
  footer: string;
  /** 已经算好的颜色。调用方用 resolve_shot_theme 从偏好里推出来。 */
  theme: ShotTheme;
  /** 图片背景。读不出来或者跨域不让用时会退回上面那套纯色。 */
  background_image?: ShotBackgroundImage;
  /** 正文字体。留空就用内置的阅读字体。 */
  body_font?: string;
}

export interface ShotRenderResult {
  width: number;
  height: number;
  scale: number;
  blob: Blob | null;
  thumb: Blob | null;
  used_blocks: number;
  total_blocks: number;
  truncated: boolean;
}

function fit(width: number, height: number, scale: number): boolean {
  const w = Math.ceil(width * scale);
  const h = Math.ceil(height * scale);
  return w <= MAX_SIDE && h <= MAX_SIDE && w * h <= MAX_PIXELS;
}

export function choose_scale(width: number, height: number): number | null {
  for (const scale of SCALE_STEPS) {
    if (fit(width, height, scale)) return scale;
  }
  return null;
}

interface Measurer {
  measure: ShotMeasure;
}

/** 读取一张图片。读不到就抛错，由调用方决定退路。 */
function load_image(source: string): Promise<HTMLImageElement> {
  return new Promise((resolve, reject) => {
    const image = new Image();
    // 不加这句的话，画上跨域图片会把画布污染掉，导出时会直接抛安全错误。
    image.crossOrigin = 'anonymous';
    image.onload = () => {
      resolve(image);
    };
    image.onerror = () => {
      reject(new Error('背景图读不出来，可能是地址不对或者对方不允许跨域'));
    };
    image.src = source;
  });
}

/**
 * 等字体就绪再画，否则画布会用回退字体，导出的图和预览对不上。
 *
 * 字体列表里每一个都要等。只等第一个的话，中文字体常常还没加载完就画了，
 * 结果就是英文用上了自定义字体、中文还是回退字体。
 */
async function ensure_font_ready(family: string): Promise<void> {
  const fonts = (document as Document & { fonts?: FontFaceSet }).fonts;
  if (!fonts) return;

  const names = family
    .split(',')
    .map(part => part.trim().replace(/^["']|["']$/g, ''))
    .filter(Boolean);
  if (!names.length) return;

  const wait = Promise.all(names.map(name => fonts.load(`16px "${name}"`).catch(() => [] as FontFace[]))).then(
    () => fonts.ready,
  );

  try {
    // 中文字体动辄十几 MB，不能无限等；超时就先用回退字体画，免得界面像卡死。
    await Promise.race([
      wait,
      new Promise(resolve => {
        window.setTimeout(resolve, 4000);
      }),
    ]);
  } catch (error) {
    console.warn('[月季管家] 字体还没就绪，先用回退字体画', error);
  }
}

/** 造一个离屏画布专门用来量文字宽度。短字符串会缓存，避免逐字测量时反复调用。 */
function make_measurer(body_family: string): Measurer {
  const canvas = document.createElement('canvas');
  canvas.width = 1;
  canvas.height = 1;
  const context = canvas.getContext('2d');
  if (!context) throw new Error('这台设备不支持画布，没法生成截图');
  const cache = new Map<string, number>();
  const measure: ShotMeasure = (text, size, bold) => {
    const key = text.length <= 2 ? `${size}|${bold ? 1 : 0}|${text}` : '';
    if (key) {
      const hit = cache.get(key);
      if (hit !== undefined) return hit;
    }
    context.font = `${bold ? '600 ' : ''}${size}px ${bold ? SANS : body_family}`;
    const width = context.measureText(text).width;
    if (key) cache.set(key, width);
    return width;
  };
  return { measure };
}

function to_blob(canvas: HTMLCanvasElement, type: string, quality: number): Promise<Blob | null> {
  return new Promise(resolve => {
    if (typeof canvas.toBlob === 'function') {
      canvas.toBlob(blob => resolve(blob), type, quality);
      return;
    }
    try {
      const url = canvas.toDataURL(type, quality);
      const [, payload] = url.split(',');
      const binary = atob(payload);
      const bytes = new Uint8Array(binary.length);
      for (let index = 0; index < binary.length; index++) bytes[index] = binary.charCodeAt(index);
      resolve(new Blob([bytes], { type }));
    } catch (error) {
      console.warn('[月季管家] 导出图片失败', error);
      resolve(null);
    }
  });
}

/** 列表用的缩略图，只取顶部一段，体积压到很小。 */
async function make_thumb(source: HTMLCanvasElement): Promise<Blob | null> {
  const target_width = 240;
  const target_height = Math.min(400, Math.max(120, Math.round((source.height / source.width) * target_width)));
  const canvas = document.createElement('canvas');
  canvas.width = target_width;
  canvas.height = target_height;
  const context = canvas.getContext('2d');
  if (!context) return null;
  context.fillStyle = '#ffffff';
  context.fillRect(0, 0, target_width, target_height);
  const source_height = Math.min(source.height, Math.round(source.width * (target_height / target_width)));
  context.drawImage(source, 0, 0, source.width, source_height, 0, 0, target_width, target_height);
  return to_blob(canvas, 'image/jpeg', 0.7);
}

export async function render_shot(input: ShotRenderInput): Promise<ShotRenderResult> {
  const body_family = input.body_font?.trim() ? input.body_font.trim() : SERIF;
  await ensure_font_ready(body_family);
  const { measure } = make_measurer(body_family);
  const theme = input.theme;

  // 第一遍：按 1 倍排出真实高度。
  const probed = layout_shot({ ...input, max_height: MEASURE_LIMIT }, measure);

  let scale = choose_scale(probed.width, probed.height);
  let layout: ShotLayout = probed;
  if (scale === null) {
    // 连 1 倍都放不下：按像素预算截断高度，并只截到设备真的画得出来的长度。
    scale = 1;
    const cap = Math.min(MAX_SIDE, Math.floor(MAX_PIXELS / Math.max(1, probed.width)));
    layout = layout_shot({ ...input, max_height: cap }, measure);
  }

  const pixel_width = Math.max(1, Math.ceil(layout.width * scale));
  const pixel_height = Math.max(1, Math.ceil(layout.height * scale));

  const canvas = document.createElement('canvas');
  canvas.width = pixel_width;
  canvas.height = pixel_height;
  const context = canvas.getContext('2d');
  if (!context) throw new Error('这台设备不支持画布，没法生成截图');

  context.scale(scale, scale);
  context.textBaseline = 'top';

  // 背景：优先画图片，读不出来就退回纯色，绝不让整张图生不出来。
  let painted = false;
  if (input.background_image?.source) {
    try {
      const image = await load_image(input.background_image.source);
      if (input.background_image.mode === 'tile') {
        const pattern = context.createPattern(image, 'repeat');
        if (pattern) {
          context.fillStyle = pattern;
          context.fillRect(0, 0, layout.width, layout.height);
          painted = true;
        }
      }
      if (!painted) {
        context.drawImage(image, 0, 0, layout.width, layout.height);
        painted = true;
      }
    } catch (error) {
      console.warn('[月季管家] 背景图用不了，改用纯色', error);
    }
  }
  if (!painted) {
    context.fillStyle = theme.background;
    context.fillRect(0, 0, layout.width, layout.height);
  }

  for (const item of layout.items) {
    if (item.kind === 'divider') {
      context.strokeStyle = theme.line;
      context.lineWidth = 1;
      context.beginPath();
      context.moveTo(item.x, item.y + 0.5);
      context.lineTo(layout.width - item.x, item.y + 0.5);
      context.stroke();
      continue;
    }
    const bold = item.bold ? '600 ' : '';
    const family = item.kind === 'text' ? body_family : SANS;
    context.font = `${bold}${item.size}px ${family}`;
    context.fillStyle = item.kind === 'name' || item.kind === 'footer' ? theme.muted : theme.ink;
    context.fillText(item.text, item.x, item.y);
  }

  const blob = await to_blob(canvas, 'image/jpeg', 0.9);
  const thumb = await make_thumb(canvas);

  return {
    width: pixel_width,
    height: pixel_height,
    scale,
    blob,
    thumb,
    used_blocks: layout.used_blocks,
    total_blocks: layout.total_blocks,
    truncated: layout.truncated,
  };
}
